/* Lot 116: the body's percentage width against html's margin and padding (generated by scripts/lot116_gen.py; expectations from scripts/lot116_model.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_sitecss.h"

static wf_site_t g_d;
static char g_html[2048], g_o[512];

static void prep(const char *css) {
    snprintf(g_html, sizeof(g_html), "<html><head><style>@keyframes k { from { color: #000000 } to { color: "
             "#ffffff } } %s #i { animation: k 1s linear; animation-timeline: scroll(nearest) }</style></head>"
             "<body><p id=i>i</p></body></html>", css);
    TEST_ASSERT_EQUAL(0, wf_site_prepare_ext(&g_d, g_html, (int)strlen(g_html), 640, 480, 0, 0));
}

static const char *style_of(const char *tag) {
    int i;
    g_o[0] = 0;
    for (i = 0; i < g_d.nnodes; i++)
        if (!strcmp(g_d.node[i].tag, tag)) wf_site_style_attr(&g_d, g_d.node[i].start, g_o, (int)sizeof(g_o));
    return g_o;
}

static void test_l116_bodyw_0(void) {
    prep("html { overflow: hidden; padding: 10px } body { overflow: auto; width: 100%; height: 100px }");
    TEST_ASSERT_NOT_NULL(strstr(style_of("body"), "width:620px\""));
    prep("html { overflow: hidden; margin: 300px; padding: 1px 2px 3px } body { overflow: auto; width: 75%; height: 100px }");
    TEST_ASSERT_NOT_NULL(strstr(style_of("body"), "width:94px\""));
    prep("html { overflow: hidden; margin: 0 255px } body { overflow: auto; width: 12%; max-width: 60%; height: 100px }");
    TEST_ASSERT_NOT_NULL(strstr(style_of("body"), "width:15px;"));
    TEST_ASSERT_NOT_NULL(strstr(style_of("body"), "max-width:78px\""));
    prep("html { overflow: hidden; padding: 100px 0 0 100px } body { overflow: auto; width: 12%; height: 100px }");
    TEST_ASSERT_NOT_NULL(strstr(style_of("body"), "width:64px\""));
    prep("html { overflow: hidden; margin: 4px 8px 12px 16px; padding: 100px 0 0 100px } body { overflow: auto; width: 150%; max-width: 60%; height: 100px }");
    TEST_ASSERT_NOT_NULL(strstr(style_of("body"), "width:774px;"));
    TEST_ASSERT_NOT_NULL(strstr(style_of("body"), "max-width:309px\""));
    prep("html { overflow: hidden; margin: 100px 0 0 100px; padding: 300px } body { overflow: auto; width: 100%; height: 100px }");
    TEST_ASSERT_NOT_NULL(strstr(style_of("body"), "width:30px\""));
    prep("html { overflow: hidden; margin: 4px 8px 12px 16px; padding: 0 255px } body { overflow: auto; width: 33%; max-width: 40%; height: 100px }");
    TEST_ASSERT_NOT_NULL(strstr(style_of("body"), "width:34px;"));
    TEST_ASSERT_NOT_NULL(strstr(style_of("body"), "max-width:42px\""));
    prep("html { overflow: hidden; padding: 2px 0 } body { overflow: auto; width: 75%; max-width: 40%; height: 100px }");
    TEST_ASSERT_NOT_NULL(strstr(style_of("body"), "width:480px;"));
    TEST_ASSERT_NOT_NULL(strstr(style_of("body"), "max-width:256px\""));
    prep("html { overflow: hidden; margin: 4px 8px 12px 16px } body { overflow: auto; width: 50%; max-width: 60%; height: 100px }");
    TEST_ASSERT_NOT_NULL(strstr(style_of("body"), "width:308px;"));
    TEST_ASSERT_NOT_NULL(strstr(style_of("body"), "max-width:369px\""));
    prep("html { overflow: hidden; padding: 5px 15px } body { overflow: auto; width: 150%; height: 100px }");
    TEST_ASSERT_NOT_NULL(strstr(style_of("body"), "width:915px\""));
}

